-- challenge chal_coding_pgp_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_122', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-1-2' AND is_deleted = false LIMIT 1), 'find-the-hottest-plan-node', 'Find the hottest node in an EXPLAIN ANALYZE plan', 'The CodeDev slow-query dashboard stores the EXPLAIN (ANALYZE, FORMAT JSON) output of every query that auto_explain logs. On-call developers keep blaming the top node of a plan because it shows the largest actual time. Write analyze_plan(explain) so the dashboard can show where the time really goes and which estimates were wrong.

Input (stdin, one test case): the JSON that PostgreSQL prints for EXPLAIN (ANALYZE, FORMAT JSON) - a list with one object holding "Plan", "Planning Time" and "Execution Time". Each plan node has "Node Type", optionally "Relation Name", "Plan Rows" (the planner''s estimate per execution), "Actual Total Time" (ms, average per execution), "Actual Rows" (average per execution), "Actual Loops" (how many times the node ran) and, when it has children, "Plans". Every entry of "Plans" is a child, whatever its "Parent Relationship" (Outer, Inner, Member, InitPlan, SubPlan). The fixtures have no parallel workers.

Output: {"execution_ms": <Execution Time>, "hottest": <id>, "nodes": [...]}
- Number the nodes 1, 2, 3 ... depth-first: a node, then its "Plans" in order. One dict per node in that order: {"id", "node": Node Type, "relation": Relation Name or null, "loops": Actual Loops, "self_ms", "rows", "rows_ratio"}.
- inclusive time = Actual Total Time x Actual Loops; self_ms = inclusive time of the node - sum of the inclusive times of its children, rounded to 3 decimals and never below 0 (per-loop times are rounded averages, so the difference can come out a little negative).
- rows = Actual Rows x Actual Loops.
- rows_ratio = (Actual Rows x Actual Loops) / (Plan Rows x Actual Loops), rounded to 2 decimals (above 1: the planner underestimated); null when the node never ran (Actual Loops = 0, shown as "never executed" in the text format).
- hottest = id of the node with the largest self_ms; the smallest id wins a tie.
- A plan without actual times (plain EXPLAIN, no ANALYZE) prints {"error": "no actual times: run EXPLAIN (ANALYZE, FORMAT JSON)"}.

Example: a Sort (Actual Total Time 4.630, 1 loop) over a Seq Scan on courses (3.912, 1 loop, 1240 actual rows, 1250 planned) gives the Sort self_ms 0.718, the Seq Scan self_ms 3.912 and rows_ratio 0.99, and hottest 2. The code runner has no PostgreSQL: this is plain Python over JSON.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_122');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_122'), 1, 'An inner Index Scan shows actual time 0.064 ms and loops 18204. How many milliseconds did the query really spend in it, and how much of its parent''s time is then left for the parent itself?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_122'), 2, 'Look at the two numbers you multiply for every node - for the node itself and for each of its children - and at which children you subtract: a SubPlan or an InitPlan sits in "Plans" next to Outer and Inner. Then check a node with "Actual Loops": 0 before you divide by anything.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_122'), 3, 'A similar walk on a different plan: a Hash Join (Actual Total Time 50.0, loops 1) has a Seq Scan child (30.0, loops 1) and a Hash child (8.0, loops 1), and the Hash has a Seq Scan child (7.9, loops 1). Inclusive times are 50.0, 30.0, 8.0 and 7.9; self times are 50.0 - 30.0 - 8.0 = 12.0 for the join, 30.0, 8.0 - 7.9 = 0.1 for the Hash and 7.9. A recursive function that returns nothing and appends one dict per node to a shared list keeps the depth-first order for free.');
