-- challenge chal_coding_pgp_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_132', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-1-3' AND is_deleted = false LIMIT 1), 'estimate-selectivity-from-pg-stats', 'Estimate selectivity from pg_stats', 'After the trial import the CodeDev team wants a check in the deploy pipeline: given the pg_stats numbers of a table and the WHERE clause of a hot query, predict the planner''s row estimate and whether it would use an index, so a misestimate shows up before the release instead of in production. Write estimate(case) with the planner''s selectivity rules in this simplified form. The code runner has no PostgreSQL: this is plain Python over pg_stats-like JSON.

Input (stdin, one test case): {"table", "rows": table row count, "stats": {column: {"null_frac", "n_distinct", "most_common_vals", "most_common_freqs", "histogram_bounds"}}, "where": [{"column", "op", "value"}] (joined by AND), "indexes": [{"name", "columns"}]}. A list in stats can be null (count it as empty); a column missing from stats was never analyzed. Range predicates and histograms use numbers only.

Selectivity of one predicate (mcv / mcf = most_common_vals / most_common_freqs):
- nd = n_distinct when it is positive, otherwise -n_distinct x rows (a negative n_distinct is a fraction of the rows).
- rest = max(0, 1 - sum(mcf) - null_frac): the share of rows outside the MCV list and the NULLs.
- "=" v: the frequency of v when v is in mcv, otherwise rest / max(1, nd - len(mcv)).
- "IS NULL": null_frac.
- "<" v: sum of mcf whose value < v + rest x frac(v).  ">" v: sum of mcf whose value > v + rest x (1 - frac(v)).
- "BETWEEN" [lo, hi]: sum of mcf with lo <= value <= hi + rest x (frac(hi) - frac(lo)).
- frac(x) = share of the histogram below x. Bounds b0..bk form k buckets with the same number of rows: x <= b0 gives 0, x >= bk gives 1, otherwise, with i the last index where b_i <= x, frac = (i + (x - b_i) / (b_{i+1} - b_i)) / k. Without a histogram (null or fewer than 2 bounds), "<" and ">" use 0.5 instead of frac(v) and 1 - frac(v), and BETWEEN uses 0.005 instead of frac(hi) - frac(lo).
- Clamp every selectivity to [0, 1].
- A column without stats uses PostgreSQL''s defaults: "=" 0.005, "<" and ">" 1/3, "BETWEEN" 0.005, "IS NULL" 0.005.
- Any other op prints {"error": "unsupported operator: <op>"}.

Output: {"selectivities": [one per predicate, in order, rounded to 6 decimals], "selectivity": product of all of them (predicates are assumed independent), rounded to 6 decimals, "rows": max(1, floor(product x rows + 0.5)), "plan": "Index Scan using <name>" or "Seq Scan"}.
Index choice: an index is usable when a predicate uses its first column; its selectivity is the product of the predicates on that column. Take the usable index with the lowest selectivity (the first one in the list on a tie). With no usable index, or when that selectivity is above 0.05, the plan is "Seq Scan" (simplified: the real crossover depends on costs and on how the rows are ordered on disk). Compute products and comparisons with unrounded values.

Example: enrollments with 20,000,000 rows, status MCVs {active 0.7, completed 0.2, cancelled 0.08, refunded 0.02}, course_id n_distinct 1840 with MCVs 7, 12, 3 (0.031, 0.024, 0.019). WHERE status = ''cancelled'' AND course_id = 42 gives 0.08 and 0.926 / 1837 = 0.000504, rows 807, and the course_id index.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_132');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_132'), 1, 'status has the MCVs active 0.71, completed 0.21 and cancelled 0.08 and no NULLs. What share of the rows is left for every value that is not in the list, and what does that make the estimate for ''trial''?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_132'), 2, 'Work through the rules in order for each predicate: first decide whether the column has stats at all, then compute nd and rest once, then branch on the operator. For ranges, the MCV part and the histogram part are added, and only the histogram part is scaled by rest. For the plan, look only at predicates on the first column of each index, and check how the threshold treats a selectivity of exactly 0.05.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_132'), 3, 'A similar range on different numbers: score has null_frac 0.1, MCVs {100: 0.2}, histogram bounds [0, 20, 50, 60, 90] (4 buckets). rest = 1 - 0.2 - 0.1 = 0.7. For score < 55: no MCV is below 55; 55 lies in bucket 2 (50..60), so frac = (2 + 5 / 10) / 4 = 0.625 and the selectivity is 0.7 x 0.625 = 0.4375. For score > 55: 0.2 (the MCV 100) + 0.7 x 0.375 = 0.4625.');
