       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_132'), 'Negative n_distinct: user_id has 0.0125 x 48M distinct values', '{"table":"activity_log","rows":48000000,"stats":{"user_id":{"null_frac":0,"n_distinct":-0.0125,"most_common_vals":[1,2,31],"most_common_freqs":[0.0009,0.0007,0.0005],"histogram_bounds":[4,1200,9800,31000,70500,122000,180400,260000,350100,455000,600010]},"kind":{"null_frac":0,"n_distinct":12,"most_common_vals":["lesson_viewed","lesson_completed","quiz_submitted","signed_in"],"most_common_freqs":[0.41,0.22,0.18,0.11],"histogram_bounds":null}},"where":[{"column":"kind","op":"=","value":"quiz_submitted"},{"column":"user_id","op":"=","value":90210}],"indexes":[{"name":"activity_log_kind_idx","columns":["kind"]},{"name":"activity_log_created_at_idx","columns":["created_at"]},{"name":"activity_log_user_id_created_at_idx","columns":["user_id","created_at"]}]}', '{"selectivities":[0.18,0.000002],"selectivity":0,"rows":14,"plan":"Index Scan using activity_log_user_id_created_at_idx"}', 3, false, true, 4),
