-- challenge chal_quiz_pgp_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_pgp_211', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-2-1' AND is_deleted = false LIMIT 1), 'index-for-pattern-plans', 'Index for the pattern: read two plans', 'Two plans from the CodeDev database: the "My courses" page after the indexes were reworked, and the weekly activity count still on the old one-column indexes. Decide whether each statement is true or false.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_211');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_211');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_211'), 'Query of the "My courses" page, index enrollments_user_created ON enrollments (user_id, created_at):
SELECT id, course_id, status, created_at FROM enrollments
WHERE user_id = 4812 ORDER BY created_at DESC LIMIT 20;

Limit  (cost=0.43..21.30 rows=20 width=32) (actual time=0.031..0.074 rows=20 loops=1)
  ->  Index Scan Backward using enrollments_user_created on enrollments  (cost=0.43..77.65 rows=74 width=32) (actual time=0.030..0.069 rows=20 loops=1)
        Index Cond: (user_id = 4812)
Planning Time: 0.142 ms
Execution Time: 0.093 ms

Statement: "The ascending index (user_id, created_at) serves ORDER BY created_at DESC: the plan has no Sort node and the scan stops after 20 index entries."', 'single_choice'::question_type, 'True. Inside one user_id the index entries are already sorted by created_at, and a B-tree can be read in both directions, so PostgreSQL reads it backward (Index Scan Backward) and needs no Sort. The Index Scan reports actual rows=20 although about 74 rows match: the Limit stops it as soon as it has 20. The common misconception is that ORDER BY ... DESC needs an index declared DESC; that only matters when columns are sorted in mixed directions, such as ORDER BY a ASC, b DESC.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_211'), 'Weekly activity count, with the old one-column indexes activity_log_user_id (user_id) and activity_log_created_at (created_at):
SELECT count(*) FROM activity_log
WHERE user_id = 4812 AND created_at >= ''2026-10-19'' AND created_at < ''2026-10-26'';

Aggregate  (cost=1873.52..1873.53 rows=1 width=8) (actual time=14.902..14.904 rows=1 loops=1)
  ->  Bitmap Heap Scan on activity_log  (cost=1866.10..1873.51 rows=3 width=0) (actual time=14.890..14.897 rows=9 loops=1)
        Recheck Cond: ((user_id = 4812) AND (created_at >= ''2026-10-19 00:00:00+00''::timestamptz) AND (created_at < ''2026-10-26 00:00:00+00''::timestamptz))
        Heap Blocks: exact=9
        ->  BitmapAnd  (cost=1866.10..1866.10 rows=3 width=0) (actual time=14.861..14.862 rows=0 loops=1)
              ->  Bitmap Index Scan on activity_log_user_id  (cost=0.00..21.40 rows=1610 width=0) (actual time=0.188..0.188 rows=1702 loops=1)
                    Index Cond: (user_id = 4812)
              ->  Bitmap Index Scan on activity_log_created_at  (cost=0.00..1844.45 rows=148000 width=0) (actual time=14.420..14.420 rows=151380 loops=1)
                    Index Cond: ((created_at >= ''2026-10-19 00:00:00+00''::timestamptz) AND (created_at < ''2026-10-26 00:00:00+00''::timestamptz))
Execution Time: 14.951 ms

Statement: "Both WHERE columns already have an index and PostgreSQL combines them with BitmapAnd, so one composite index on (user_id, created_at) would read about as many index entries as this plan."', 'single_choice'::question_type, 'False. The BitmapAnd has to build both bitmaps in full: 1,702 entries for the user and 151,380 entries for the whole week of every user (almost all of the 14.4 ms), only to keep the 9 rows where they overlap. A composite index (user_id, created_at) descends straight to this user''s entries inside the range and reads about 9 entries, and it can answer count(*) with an Index Only Scan. The misconception is that "every column has an index" means the query is indexed: combining one-column indexes is a fallback whose cost grows with the least selective condition, not with the result.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_pgp_212 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_212', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-2-1' AND is_deleted = false LIMIT 1), 'indexes-for-three-query-patterns', 'Indexes for three query patterns', 'Three queries of CodeDev are at the top of pg_stat_statements, and the database has one index per column that appears in a WHERE or ORDER BY. Replace INDEXES (a SQL string in the starter) with at most 3 CREATE INDEX statements so that SQLite searches an index for every query.

Tables (created and filled by the runner before INDEXES is applied): enrollments(id INTEGER PRIMARY KEY, user_id, course_id, created_at, status) and activity_log(id INTEGER PRIMARY KEY, user_id, kind, created_at). The queries, run exactly as written:
- my_courses: SELECT id, course_id, status, created_at FROM enrollments WHERE user_id = ? ORDER BY created_at DESC LIMIT 20
- weekly_activity: SELECT count(*) FROM activity_log WHERE user_id = ? AND created_at >= ? AND created_at < ?
- course_learners: SELECT user_id, created_at FROM enrollments WHERE course_id = ? AND status = ?

Input (stdin): either the rows of both tables or a "generate" spec for a large deterministic data set, plus the parameters of each query. Output: one JSON object with, for each query, {"plan": verdict, "rows": rows} (course_learners rows sorted by the runner), and "indexes": "ok" or "too many indexes: N (at most 3)". The plan verdict comes from SQLite''s EXPLAIN QUERY PLAN: "ok" when every WHERE column is used to search the index (and, for my_courses, there is no USE TEMP B-TREE FOR ORDER BY); "full scan of <table>" for SCAN (including SCAN ... USING INDEX, which reads every index entry); "index does not narrow by <column>" when the search uses only some of the WHERE columns; "sorts with a temp B-tree" when my_courses is sorted after reading. INDEXES may only contain CREATE INDEX statements, and the rows must stay what the queries return without indexes. Every test expects every plan "ok", the correct rows and "indexes": "ok".

SQLite and PostgreSQL use the same CREATE INDEX syntax and the same B-tree rules for these patterns. The runner does not run ANALYZE, so SQLite plans from the indexes alone.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_212');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_212'), 1, 'For each query, which columns are compared with =, which one is a range, and which one decides the order of the rows? An index is sorted by its first column, then by the second column inside equal first values.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_212'), 2, 'Run the starter and read the verdicts one query at a time: "sorts with a temp B-tree" means the index found the rows but not in the right order, and "does not narrow by" names the column the index search could not use. Then count how many indexes the three queries really need: two of them read the same table but filter on different columns.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_212'), 3, 'A similar pattern on another table: SELECT lesson_id, completed_at FROM lesson_progress WHERE course_id = ? ORDER BY completed_at DESC LIMIT 10 is served by CREATE INDEX lesson_progress_course_completed ON lesson_progress (course_id, completed_at): the equality column first, the ORDER BY column second. An index on (completed_at) alone gives the order but walks through every course; an index on (course_id) alone finds the rows but has to sort them.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_212'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
