-- challenge chal_coding_pgp_222 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_222', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-2-2' AND is_deleted = false LIMIT 1), 'fix-the-case-insensitive-sign-in', 'Fix the sign-in that stopped using its index', 'Release 2026.10.20 made sign-in on CodeDev case-insensitive by changing the query to SELECT id FROM users WHERE lower(email) = lower(?). Since then sign-in is slow: the users table has a unique index on email, yet EXPLAIN QUERY PLAN shows the query reading every user. Fix SCHEMA and/or SIGN_IN_QUERY in the starter so that sign-in searches an index and stays case-insensitive.

Emails are stored as the user typed them at sign-up, in any case (for example "Linh.Tran@CodeDev.test"); no two stored emails differ only in case, and they contain only ASCII letters, digits and . _ % @. SIGN_IN_QUERY receives one parameter, the email typed on the sign-in form, and returns the ids of the matching users. Characters such as _ and % are part of the email, not wildcards.

Input (stdin): {"users": [[id, email, created_at], ...], "attempts": [typed emails]} or {"generate": N, "attempts": [...]} for N generated users. The runner applies SCHEMA to an empty database, inserts the users with INSERT INTO users (id, email, created_at) VALUES (?, ?, ?), then runs SIGN_IN_QUERY once per attempt.

Output: {"plan": ..., "sign_ins": [...]}. plan is "uses an index" when EXPLAIN QUERY PLAN shows SEARCH users ... INDEX, otherwise "full scan of users" (SCAN users USING COVERING INDEX is still a full scan: it reads every index entry). sign_ins has one entry per attempt: the sorted list of matching ids ([] for no account), or "too slow" when one sign-in needs more than 20,000 SQLite VM steps (counted with set_progress_handler; the large test has 20,000 users). Every test checks both: the plan and the ids.

SQLite, like PostgreSQL, supports indexes on expressions; SQLite''s lower() and COLLATE NOCASE fold ASCII letters only, and SQLite has no citext or ILIKE.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
