WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_231'), 'Feed of a learner with only 3 events, index activity_log_created_user ON activity_log (created_at, user_id), activity_log has 40M rows:
SELECT id, kind, created_at FROM activity_log
WHERE user_id = 9001 ORDER BY created_at DESC LIMIT 20;

Limit  (cost=0.56..499855.49 rows=20 width=40) (actual time=1843.551..1843.560 rows=3 loops=1)
  ->  Index Scan Backward using activity_log_created_user on activity_log  (cost=0.56..824761.20 rows=33 width=40) (actual time=1843.549..1843.556 rows=3 loops=1)
        Index Cond: (user_id = 9001)
        Buffers: shared hit=171032 read=29871
Execution Time: 1843.602 ms

Statement: "Because user_id appears in Index Cond, the index took the scan straight to the entries of user 9001, as an index on (user_id, created_at) would."', 'single_choice'::question_type, 'False. An Index Cond on a column that is not the leading column is checked on every index entry, not used to jump to a starting point. The index is sorted by created_at first, so the entries of user 9001 are spread across the whole index: PostgreSQL walks it backward from the newest entry and tests user_id on each one. The Limit can only stop early after 20 matches; this learner has 3, so the scan reads the entire index (about 200,000 buffers, 1.8 s). With (user_id, created_at) the scan starts at the user''s newest entry and stops after at most 20 entries. The misconception is to read "Index Scan ... Index Cond" as proof of a narrow search; the buffer count and the time say otherwise.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_231'), 'Course roster, index enrollments_status_course ON enrollments (status, course_id), enrollments has 6M rows:
SELECT user_id, status FROM enrollments WHERE course_id = 17;

Seq Scan on enrollments  (cost=0.00..113496.00 rows=1180 width=12) (actual time=0.412..402.118 rows=1204 loops=1)
  Filter: (course_id = 17)
  Rows Removed by Filter: 5998796
Execution Time: 402.301 ms

Statement: "The planner ignores enrollments_status_course here because course_id is not its leading column; an index on (course_id, status) would serve both WHERE course_id = ? and WHERE course_id = ? AND status = ?."', 'single_choice'::question_type, 'True. A B-tree on (status, course_id) is sorted by status first, so rows of course 17 sit in three separate runs, one per status, and without a condition on status there is no single place to start. PostgreSQL 16-17 then prefers a Seq Scan (PostgreSQL 18 can sometimes skip-scan a leading column with few values, at extra cost). An index on (course_id, status) has every row of course 17 together, so it serves the roster by its leading column alone and the filtered roster by both columns. The misconception is that the column with fewer distinct values should go first; for equality conditions the order does not change selectivity, but it decides which queries can use the index at all.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_pgp_232 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_232', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-2-3' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-composite-index-order', 'Spot the AI Mistake: composite index column order', 'A developer sent this request to an AI assistant: "Add indexes for these three queries. activity_log has 40M rows, enrollments 6M. Add at most one index per table: every index slows down our writes. feed: SELECT id, kind, created_at FROM activity_log WHERE user_id = ? ORDER BY created_at DESC LIMIT 20; roster: SELECT user_id, status FROM enrollments WHERE course_id = ?; roster_by_status: SELECT user_id, status FROM enrollments WHERE course_id = ? AND status = ?". The assistant answered with the two indexes in INDEXES and the note "created_at goes first because the feed sorts by it; status goes first because it has only three values." The results of all three queries were correct in review and the change was merged, but production still reads millions of rows for a quiet learner''s feed and for a course roster. Fix INDEXES: at most 2 CREATE INDEX statements, queries unchanged.

Tables (created and filled by the runner before INDEXES is applied): activity_log(id INTEGER PRIMARY KEY, user_id, kind, created_at) and enrollments(id INTEGER PRIMARY KEY, user_id, course_id, created_at, status).

Input (stdin): the rows of both tables or a "generate" spec for a large deterministic data set, "calls" ([{"query": "feed" | "roster" | "roster_by_status", "params": [...]}, ...]) and optionally "explain": true.

Output: {"indexes": "ok" or "too many indexes: N (at most 2)", "calls": [...]}, one entry per call: "rows" (roster rows sorted by the runner), or "too slow" when the call needs more than 20,000 SQLite VM steps (counted with set_progress_handler; the large tests have 40,000 activity rows and 12,000 enrollments); with "explain": true also "plan", a verdict from EXPLAIN QUERY PLAN: "ok" (every WHERE column searches the index and the feed needs no USE TEMP B-TREE FOR ORDER BY), "full scan of <table>" (SCAN, including SCAN ... USING INDEX), "index does not narrow by <column>" or "sorts with a temp B-tree". The public tests check the rows, as the review did; the hidden tests check the plans and the step budget on large tables. The runner does not run ANALYZE.', 'open', 'hard'::difficulty_question, 'fix_bug', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_232');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_232'), 1, 'For the feed of a learner with only 3 events, where in an index sorted by (created_at, user_id) are those 3 entries, and how many entries must be read before the query knows there is no fourth one?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_232'), 2, 'Read the assistant''s two reasons against the queries: which column is compared with = in every query that uses each index, and which column only decides the order? Then check the roster query: which index column does it give a value for?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_232'), 3, 'A similar pair on another table: SELECT lesson_id FROM lesson_progress WHERE course_id = ? ORDER BY completed_at DESC LIMIT 10 needs (course_id, completed_at), not (completed_at, course_id): the first finds the course''s entries in order and stops after 10, the second walks every course''s entries. And an index on (user_id, course_id) serves WHERE user_id = ? and WHERE user_id = ? AND course_id = ?, but not WHERE course_id = ? alone.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_232'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
