-- challenge chal_quiz_pgp_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_pgp_311', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-3-1' AND is_deleted = false LIMIT 1), 'n-plus-one-evidence', 'Read the N+1 evidence', 'Two pieces of evidence from the slow "My learning" page: an APM trace next to pg_stat_statements, and the EXPLAIN ANALYZE of the single query that replaced the loop. Decide whether each statement is true or false.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_311');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_311');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_311'), 'APM trace of one request:

GET /api/me/courses  user_id=4812  status=200  duration=412 ms
  db.query  SELECT course_id FROM enrollments WHERE user_id = $1 ...      3.1 ms  x1
  db.query  SELECT title FROM courses WHERE id = $1                       2.8 ms  x60
  db.query  SELECT count(DISTINCT lesson_id) FROM lesson_progress ...    3.4 ms  x60
  db spans: 121, db time: 376 ms

pg_stat_statements, same hour:
 query                                                  |  calls | mean_exec_time
--------------------------------------------------------+--------+---------------
 SELECT title FROM courses WHERE id = $1                | 912340 |          0.021
 SELECT count(DISTINCT lesson_id) FROM lesson_progress  | 912338 |          0.048
   WHERE user_id = $1 AND course_id = $2 ...            |        |

Statement: "Both per-course queries run in well under 0.1 ms inside PostgreSQL, so the 120 per-course queries cannot explain most of the 412 ms; the time must be spent somewhere else in the request."', 'single_choice'::question_type, 'False. mean_exec_time measures only the time PostgreSQL spends executing the statement. The APM span is what the application waits for: taking a connection from the pool, sending the query over the network, parse and bind, executing, and reading the answer back. Here that is about 3 ms per query, almost all of it outside the executor, and it is paid 121 times: 60 x 2.8 ms + 60 x 3.4 ms + 3.1 ms is about 375 ms, the 376 ms of db time in the trace. The common misconception is that a query that is fast in pg_stat_statements is cheap to call. The cost of N+1 is per round trip, and it grows with N.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_311'), 'EXPLAIN (ANALYZE) of the query that replaced the loop, same learner (60 active enrollments):

Sort  (cost=96.71..96.86 rows=60 width=44) (actual time=0.981..0.986 rows=60 loops=1)
  Sort Key: e.created_at DESC, e.id DESC
  Sort Method: quicksort  Memory: 30kB
  ->  GroupAggregate  (cost=91.40..94.94 rows=60 width=44) (actual time=0.402..0.955 rows=60 loops=1)
        Group Key: e.id, c.id
        ->  Sort  (cost=91.40..92.57 rows=468 width=40) (actual time=0.391..0.437 rows=457 loops=1)
              Sort Key: e.id, c.id
              Sort Method: quicksort  Memory: 61kB
              ->  Nested Loop Left Join  (cost=0.99..70.55 rows=468 width=40) (actual time=0.031..0.298 rows=457 loops=1)
                    ->  Nested Loop  (cost=0.57..37.10 rows=60 width=36) (actual time=0.022..0.121 rows=60 loops=1)
                          ->  Index Scan using enrollments_user_id_course_id_key on enrollments e  (cost=0.29..9.47 rows=62 width=20) (actual time=0.013..0.031 rows=60 loops=1)
                                Index Cond: (user_id = 4812)
                                Filter: (status <> ''cancelled''::text)
                                Rows Removed by Filter: 2
                          ->  Index Scan using courses_pkey on courses c  (cost=0.28..0.45 rows=1 width=24) (actual time=0.001..0.001 rows=1 loops=60)
                                Index Cond: (id = e.course_id)
                    ->  Index Scan using lesson_progress_user_course on lesson_progress lp  (cost=0.42..0.48 rows=8 width=12) (actual time=0.001..0.002 rows=8 loops=60)
                          Index Cond: ((user_id = 4812) AND (course_id = e.course_id))
                          Filter: (completed_at IS NOT NULL)
                          Rows Removed by Filter: 1
Planning Time: 0.388 ms
Execution Time: 1.032 ms

Statement: "The index scan on lesson_progress still runs 60 times (loops=60), but all 60 lookups happen inside this one statement, so the page now pays for one round trip instead of 121."', 'single_choice'::question_type, 'True. loops=60 means the inner side of the nested loop was executed once per enrollment row, but that happens inside the executor: each lookup takes about 0.002 ms and no network, pool or driver work sits between them. The whole statement executes in about 1 ms and the application sends it once. The common misconception is to read loops=N in a plan as "still N+1". A nested loop join is often the right plan for a few dozen outer rows; N+1 is about round trips between the application and the database, not about how many times an index is probed.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_311') AND order_index = 2)
    RETURNING id
)
