        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_pgp_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_312', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-3-1' AND is_deleted = false LIMIT 1), 'my-learning-one-query', 'One query for the "My learning" page', 'The "My learning" page of CodeDev sends 1 + 2N queries per view: the learner''s enrollments, then the title and the finished-lesson count of every course, one query each. Rewrite load_my_courses(db, user_id) so that it calls db.execute exactly once and returns the same rows: one [course_id, title, completed_lessons] per enrollment of the user whose status is not ''cancelled'' (''active'' and ''completed'' count), where completed_lessons is the number of different lessons of that course the user finished (lesson_progress.completed_at not NULL; the same finished lesson can be stored twice, and a course with nothing finished must still appear with 0). Progress of other users and of courses the user is not enrolled in never counts. Order by enrollments.created_at DESC, then enrollments.id DESC. Tables: users(id, email, created_at), courses(id, title, category, created_at), enrollments(id, user_id, course_id, created_at, status) with UNIQUE (user_id, course_id), lesson_progress(user_id, lesson_id, course_id, completed_at). The test runner at the bottom of the file builds an in-memory SQLite database from each test case, passes a connection that counts db.execute calls, and prints {"queries": <calls>, "courses": [[course_id, title, completed_lessons], ...]}. Write SQL that also runs on PostgreSQL (GROUP BY the primary keys you select from; no SQLite-only functions).', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
