INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_312'), 1, 'Which table decides how many rows the page has: enrollments, courses or lesson_progress? Start the FROM clause there, and ask what happens to a course with no finished lesson when you join the progress rows to it.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_312'), 2, 'Look at three places: the kind of join to lesson_progress (an inner join keeps only courses that have a match), where the completed_at condition sits (in ON it only chooses which progress rows join; in WHERE it also removes the NULL row a LEFT JOIN added), and what COUNT(column) does with a lesson stored twice.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_312'), 3, 'A similar query on other tables: the number of different paid products per customer, keeping customers with none. SELECT cu.id, cu.name, COUNT(DISTINCT o.product_id) FROM customers AS cu LEFT JOIN orders AS o ON o.customer_id = cu.id AND o.status = ''paid'' WHERE cu.region = :region GROUP BY cu.id, cu.name ORDER BY cu.signed_up_at DESC, cu.id DESC. The status filter sits in ON, so a customer without paid orders keeps one row of NULLs, and COUNT(DISTINCT o.product_id) skips that NULL and returns 0.');
