VALUES ('chal_quiz_pgp_321', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-3-2' AND is_deleted = false LIMIT 1), 'keyset-pagination-evidence', 'Read a keyset page', 'Two pieces of evidence from the activity feed: the plans of page 1 and of a deep page read with a (created_at, id) cursor, and a page boundary that falls inside a group of events with the same timestamp. Decide whether each statement is true or false.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
