    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_321');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_321');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_321'), 'Index: activity_log_user_created_id ON activity_log (user_id, created_at, id). User 42 has 26,090 events.

-- page 1
Limit  (cost=0.43..21.37 rows=20 width=52) (actual time=0.021..0.044 rows=20 loops=1)
  Buffers: shared hit=5
  ->  Index Scan Backward using activity_log_user_created_id on activity_log  (cost=0.43..27315.12 rows=26090 width=52) (actual time=0.020..0.040 rows=20 loops=1)
        Index Cond: (user_id = 42)
        Buffers: shared hit=5
Execution Time: 0.061 ms

-- a page about 25,000 rows deep, cursor = last row of the previous page
Limit  (cost=0.43..22.01 rows=20 width=52) (actual time=0.025..0.049 rows=20 loops=1)
  Buffers: shared hit=6
  ->  Index Scan Backward using activity_log_user_created_id on activity_log  (cost=0.43..1210.42 rows=1121 width=52) (actual time=0.024..0.045 rows=20 loops=1)
        Index Cond: ((user_id = 42) AND (ROW(created_at, id) < ROW(''2025-11-03 18:22:41.512+00''::timestamp with time zone, 77012345)))
        Buffers: shared hit=6
Execution Time: 0.068 ms

Statement: "The deep page touches about as many buffers as page 1 because the index scan starts at the cursor instead of walking past the rows of the earlier pages."', 'single_choice'::question_type, 'True. The row comparison is an Index Cond, not a Filter: the B-tree descends directly to the position of (42, ''2025-11-03 18:22:41.512'', 77012345) and reads backward from there. Both pages read 20 rows and 5-6 buffers, and both stop as soon as Limit has its 20 rows. The common misconception is that a deep page must cost more because "the database has to find where page 1250 starts". With OFFSET it does; with a keyset cursor the position is a key the index can seek to. Check it the same way: compare actual rows and Buffers of page 1 and of a deep page.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_321'), 'Completing a lesson inserts three events in one transaction, so they share created_at (now() is the start time of the transaction).

SELECT id, kind FROM activity_log
WHERE user_id = 42 AND created_at = ''2026-10-24 14:03:17.25+00'' ORDER BY id DESC;

   id    |      kind
---------+-----------------
 8812043 | streak_extended
 8812042 | lesson_completed
 8812041 | badge_earned

Page 1 (LIMIT 20, ORDER BY created_at DESC, id DESC) ended with the row 8812042. The feed then requests page 2:

SELECT id, kind, created_at FROM activity_log
WHERE user_id = 42 AND created_at < ''2026-10-24 14:03:17.25+00''
ORDER BY created_at DESC, id DESC
LIMIT 20;

Statement: "Because ORDER BY ends with id as a tie-breaker, page 2 starts with the row 8812041."', 'single_choice'::question_type, 'False. ORDER BY only decides the order of the rows that pass WHERE. The cursor condition created_at < ''...17.25'' excludes every row with exactly that timestamp, so 8812041 (badge_earned) is never shown on any page: the feed silently loses the rows of a tie group that did not fit on the previous page. The cursor has to carry the tie-breaker too: (created_at, id) < (''2026-10-24 14:03:17.25+00'', 8812042). The common misconception is that a unique ORDER BY is enough; the WHERE of the next page must use the same columns as the ORDER BY.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_pgp_322 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_322', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-3-2' AND is_deleted = false LIMIT 1), 'activity-feed-keyset-page', 'Keyset pagination for the activity feed', 'The activity feed on a CodeDev profile loads newest first with infinite scroll, and events go missing: a lesson completion writes three events in one transaction with the same created_at, and the old cursor (created_at < the last created_at) skipped the ones that did not fit on the previous page. Write NEXT_PAGE, the SQL for the page after a given last row. Table: activity_log(id INTEGER PRIMARY KEY, user_id, kind, created_at TEXT ''YYYY-MM-DD HH:MM:SS''); created_at is not unique and ids are not in time order (imported events got larger ids with their original timestamps). The runner creates the index activity_log_user_created_id ON activity_log (user_id, created_at, id). NEXT_PAGE gets the named parameters :user_id, :last_created_at, :last_id (the last row of the previous page) and :limit, and returns id, kind, created_at of the next :limit rows of that user in the order created_at DESC, id DESC, so that every row appears exactly once across all pages. Do not use OFFSET: each page must be read through the index starting at the cursor. SQLite has supported row values like (a, b) < (?, ?) since 3.15, with the same tuple comparison as PostgreSQL. The test runner at the bottom of the file runs FIRST_PAGE (given), then NEXT_PAGE with the last row of each page until a page has fewer than :limit rows, with a budget of SQLite VM steps per page (a page that reads far more rows than it returns is stopped as "too slow"), checks with EXPLAIN QUERY PLAN that NEXT_PAGE uses activity_log_user_created_id without a temporary B-tree for sorting, and prints {"pages": <pages read>, "ids": [<ids in feed order>], "plan": "ok"}.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_322');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_322'), 1, 'The next page must contain the rows that come after the last row in the order created_at DESC, id DESC. Which rows with exactly the same created_at as the last row still belong on the next page?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_322'), 2, 'Look at the columns of ORDER BY and the columns of your cursor condition: they must be the same, in the same order and direction. Then look at how the condition uses created_at: the index can only seek on the column itself, not on an expression computed from it.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_322'), 3, 'A similar case on other data: a leaderboard ordered by score DESC, user_id DESC, where the last row shown was (score 870, user_id 31). The next page is WHERE (score, user_id) < (870, 31) ORDER BY score DESC, user_id DESC LIMIT 10. It keeps (870, 12), which a cursor of score < 870 would skip, and it never returns (870, 31) or (870, 45) again.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_322'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
