-- challenge chal_quiz_pgp_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_pgp_331', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-3-3' AND is_deleted = false LIMIT 1), 'deep-offset-evidence', 'Read the deep OFFSET evidence', 'Two pieces of evidence from the admin activity pages: the plan of page 400 of the export, and two consecutive pages of the newest-first admin list while learners keep working. Decide whether each statement is true or false.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_331');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_331');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_331'), 'activity_log: 2.7 million rows, 9 GB, mostly not in shared_buffers; rows imported from the old system are not stored in created_at order. The admin API runs with statement_timeout = 5s.

EXPLAIN (ANALYZE, BUFFERS)
SELECT id, user_id, kind, created_at FROM activity_log
ORDER BY created_at, id
LIMIT 100 OFFSET 39900;            -- page 400

Limit  (cost=3418.27..3426.84 rows=100 width=52) (actual time=4805.931..4813.117 rows=100 loops=1)
  Buffers: shared hit=1204 read=38811
  ->  Index Scan using activity_log_created_id on activity_log  (cost=0.43..233512.88 rows=2725410 width=52) (actual time=0.031..4805.926 rows=40000 loops=1)
        Buffers: shared hit=1204 read=38811
Planning Time: 0.102 ms
Execution Time: 4813.215 ms

Statement: "Only the 100 rows of page 400 were read from the table; most of the 4.8 s is spent sending those rows to the client."', 'single_choice'::question_type, 'False. The Index Scan node reports actual rows=40000: PostgreSQL fetched every row of pages 1 to 400 in order, and the Limit node threw away the first 39,900 (OFFSET is applied after the rows are produced). The 38,811 buffer reads are those rows'' heap pages, read from disk because the table is not in cache and imported rows are scattered. The scan''s own actual time (4805 ms) covers almost the whole execution, and EXPLAIN ANALYZE does not even send rows to a client. The common misconception is that OFFSET jumps to a position; the database has no way to find row 39,901 of an order without producing the 39,900 rows before it, so the cost of a page grows with its number.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_331') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_331'), 'The admin activity list shows the newest events first, 100 per page, with OFFSET. API log:

10:41:07.120  GET /admin/activity?page=3   ORDER BY created_at DESC, id DESC LIMIT 100 OFFSET 200
              -> 100 rows, last two: 9120417, 9120416
10:41:09.004  INSERT activity_log id=9120533 (lesson_completed)
10:41:09.004  INSERT activity_log id=9120534 (badge_earned)
10:41:12.871  GET /admin/activity?page=4   ORDER BY created_at DESC, id DESC LIMIT 100 OFFSET 300
              -> 100 rows, first three: 9120417, 9120416, 9120415

Statement: "The two rows repeated at the top of page 4 are caused by the two events inserted between the requests; a cursor (created_at, id) < (the created_at of 9120416, 9120416) would have started page 4 at 9120415."', 'single_choice'::question_type, 'True. OFFSET 300 means "skip 300 rows of the order as it is now". Two new rows were inserted at the top of the newest-first order, so everything moved down by two positions and the last two rows of page 3 became rows 301 and 302. A keyset cursor names a position in the order by value, not by count, so rows inserted before it do not move it: page 4 starts right after 9120416. Deletes have the opposite effect with OFFSET: rows move up and some are never shown. The common misconception is that OFFSET pages are a stable snapshot; each request counts again on the data as it is at that moment.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_331') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_pgp_332 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_332', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-3-3' AND is_deleted = false LIMIT 1), 'admin-export-deep-offset', 'Fix the admin export that times out on deep pages', 'The quarterly audit export of the CodeDev activity log reads the table oldest first in pages of PAGE_SIZE rows. Since the table grew, the export job dies on deep pages (in production around page 400, with "canceling statement due to statement timeout"): each page is slower than the previous one, although each returns only PAGE_SIZE rows. Fix export_activity so that every page costs about the same and the export is exactly the same as before: the same rows, in the same order (created_at, then id), split into the same pages. Table: activity_log(id INTEGER PRIMARY KEY, user_id, kind, created_at TEXT ''YYYY-MM-DD HH:MM:SS''), with the index activity_log_created_id ON activity_log (created_at, id); created_at is not unique and ids are not in time order (imported events got larger ids with their original timestamps). db.execute(sql, params) runs one statement and returns all its rows as a list of tuples. The test runner at the bottom of the file runs every statement with a budget of SQLite VM steps (set_progress_handler, standing in for statement_timeout): a statement that reads far more rows than it returns is stopped and the runner prints {"error": "too slow: ..."}. For small tests the runner sets PAGE_SIZE from the test case. It prints {"pages": <pages>, "rows": <rows>, "head": <first 3 rows>, "tail": <last 3 rows>, "sha256": <hash of the page split and all rows>}.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_332');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_332'), 1, 'To return page 400, how many rows does the database have to produce before it can throw away the first 39,900? What do you already know at the end of page 399 that could tell the database where page 400 starts?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_332'), 2, 'Look at what the loop carries from one page to the next (a page number) and at the ORDER BY: the next page is "the rows after the last row I received in this order". Every column of ORDER BY has to be part of that condition, or rows that share a created_at get lost at a page boundary.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_332'), 3, 'A similar loop on other data: exporting submissions ordered by (score, id) in pages of 50. After a page that ended with (score 88, id 1203), the next statement is SELECT ... WHERE (score, id) > (88, 1203) ORDER BY score, id LIMIT 50. The first page has no WHERE; the loop keeps the last row of each page instead of a page number and stops when a page has fewer than 50 rows.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_332'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
