INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_332'), 'Pages of 2: events sharing a timestamp are split across a page boundary', '{"page_size":2,"rows":[[5,3,"lesson_completed","2026-07-01 09:00:00"],[7,3,"badge_earned","2026-07-01 09:00:00"],[6,3,"streak_extended","2026-07-01 09:00:00"],[2,4,"course_enrolled","2026-07-01 08:59:00"],[9,4,"lesson_completed","2026-07-01 09:30:00"]]}', '{"pages":3,"rows":5,"head":[[2,4,"course_enrolled","2026-07-01 08:59:00"],[5,3,"lesson_completed","2026-07-01 09:00:00"],[6,3,"streak_extended","2026-07-01 09:00:00"]],"tail":[[6,3,"streak_extended","2026-07-01 09:00:00"],[7,3,"badge_earned","2026-07-01 09:00:00"],[9,4,"lesson_completed","2026-07-01 09:30:00"]],"sha256":"ef2a161972d9720d"}', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_332'), 'Large: 12,000 events in pages of 100, every page within the statement budget', '{"rows":[],"bulk":{"count":12000,"start":"2026-07-01 00:00:00"}}', '{"pages":120,"rows":12000,"head":[[100000,1,"lesson_completed","2026-07-01 00:00:00"],[100001,2,"badge_earned","2026-07-01 00:00:00"],[100002,3,"streak_extended","2026-07-01 00:00:00"]],"tail":[[111997,48,"streak_extended","2026-07-01 05:49:53"],[111998,49,"challenge_passed","2026-07-01 05:49:53"],[111999,50,"course_enrolled","2026-07-01 05:49:53"]],"sha256":"7f6248c906fe46fb"}', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_332'), 'A whole page of rows with the same timestamp', '{"page_size":2,"rows":[[14,1,"lesson_completed","2026-07-02 12:00:00"],[11,2,"badge_earned","2026-07-02 12:00:00"],[13,1,"streak_extended","2026-07-02 12:00:00"],[12,3,"challenge_passed","2026-07-02 12:00:00"],[15,2,"badge_earned","2026-07-02 12:00:00"],[10,1,"course_enrolled","2026-07-02 12:00:01"]]}', '{"pages":3,"rows":6,"head":[[11,2,"badge_earned","2026-07-02 12:00:00"],[12,3,"challenge_passed","2026-07-02 12:00:00"],[13,1,"streak_extended","2026-07-02 12:00:00"]],"tail":[[14,1,"lesson_completed","2026-07-02 12:00:00"],[15,2,"badge_earned","2026-07-02 12:00:00"],[10,1,"course_enrolled","2026-07-02 12:00:01"]],"sha256":"57b7f7f535c72bde"}', 2, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_332'), 'Imported events with large ids and old timestamps keep their place', '{"page_size":3,"rows":[[101,1,"lesson_completed","2026-07-03 08:00:00"],[102,2,"lesson_completed","2026-07-03 09:00:00"],[900,1,"course_enrolled","2025-01-15 10:00:00"],[103,3,"badge_earned","2026-07-03 10:00:00"],[901,2,"lesson_completed","2025-01-15 10:00:00"],[104,1,"challenge_passed","2026-07-03 11:00:00"],[902,3,"streak_extended","2025-02-01 07:00:00"]]}', '{"pages":3,"rows":7,"head":[[900,1,"course_enrolled","2025-01-15 10:00:00"],[901,2,"lesson_completed","2025-01-15 10:00:00"],[902,3,"streak_extended","2025-02-01 07:00:00"]],"tail":[[102,2,"lesson_completed","2026-07-03 09:00:00"],[103,3,"badge_earned","2026-07-03 10:00:00"],[104,1,"challenge_passed","2026-07-03 11:00:00"]],"sha256":"f9cb21e6735b82f7"}', 2, false, true, 4),
