-- challenge chal_quiz_pgp_411 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_pgp_411', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-4-1' AND is_deleted = false LIMIT 1), 'progress-report-plan-quiz', 'Read the slow report''s plan and check a rewrite', 'Two pieces of evidence from the nightly progress report incident: the auto_explain plan of the report that ran for 40 minutes, and a first attempt at rewriting it with a join. Decide whether each statement is true or false.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_411');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_411');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_411'), 'The old challenge section of the same nightly report computed each learner''s average best score with a subquery per row of report_learners, a work table the job fills first with one row per (learner, course). Part of its auto_explain plan (PostgreSQL 16):

->  Seq Scan on report_learners rl  (cost=0.00..46121488.30 rows=389114 width=16) (actual time=0.402..1117962.113 rows=389114 loops=1)
      SubPlan 1
        ->  Aggregate  (cost=118.43..118.44 rows=1 width=32) (actual time=2.871..2.871 rows=1 loops=389114)
              ->  Index Scan using submissions_user_id_idx on submissions s  (cost=0.43..118.40 rows=12 width=4) (actual time=0.214..2.862 rows=16 loops=389114)
                    Index Cond: (user_id = rl.user_id)
                    Filter: (course_id = rl.course_id)
                    Rows Removed by Filter: 41

Statement: "SubPlan 1 accounts for roughly 18 minutes of the run: its actual time is per loop, and it ran once for every (learner, course) row."', 'single_choice'::question_type, 'True. In EXPLAIN ANALYZE, actual time and rows of a node are averages per loop, so the total is time x loops: 2.871 ms x 389,114 loops is about 1,117 seconds (18.6 minutes), which matches the 1,117,962 ms the Seq Scan above it reports. Each execution is a cheap index scan; what makes it expensive is that a correlated subquery runs again for every outer row. The misconception is to read 2.871 ms as the cost of the node and conclude the subquery is fast: always multiply by loops.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_411') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_411'), 'A first rewrite of the report''s enrolled column. enrollments has UNIQUE (user_id, course_id), and lesson_progress has one row per (user_id, lesson_id) a learner has opened.

SELECT e.course_id,
       COUNT(*) AS enrolled
FROM enrollments AS e
JOIN lesson_progress AS lp
  ON lp.user_id = e.user_id AND lp.course_id = e.course_id
WHERE e.status <> ''cancelled''
GROUP BY e.course_id
ORDER BY e.course_id;

Old report, course 7: enrolled = 2 (learner 1 opened 4 lessons, learner 2 opened 2 lessons).

Statement: "For course 7 this query also returns enrolled = 2, because the unique key allows only one enrollment per learner and course."', 'single_choice'::question_type, 'False. The unique key limits enrollments, not the joined rows. The join produces one row per progress row of each learner, so course 7 gets 4 + 2 = 6 rows and COUNT(*) returns 6. The inner join also drops learners who have not opened any lesson, so the number can be too high and too low at once. Aggregate the child table to one row per (user, course) first, then join, or count the parent''s key with COUNT(DISTINCT e.id). The misconception is that a unique key on the parent protects a count taken after a one-to-many join: it is the join that multiplies the rows (fan-out).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_411') AND order_index = 2)
    RETURNING id
)
