        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_pgp_412 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_412', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-4-1' AND is_deleted = false LIMIT 1), 'rewrite-progress-report', 'Rewrite the nightly progress report', 'The nightly progress report of CodeDev ran for 40 minutes: it computes three numbers per course with correlated subqueries, one subquery run per course and, inside it, one per enrollment. Rewrite QUERY in the starter so it returns exactly the same rows but reads each table in one pass (CTEs, joins, GROUP BY). You may also add indexes in INDEXES (optional).

Tables: courses(id, title, category, created_at), lessons(id, course_id, position), users(id, email, created_at), enrollments(id, user_id, course_id, created_at, status) with UNIQUE (user_id, course_id) and status ''active'', ''completed'' or ''cancelled'', lesson_progress(user_id, lesson_id, course_id, completed_at) with PRIMARY KEY (user_id, lesson_id); completed_at NULL means the lesson was opened but not finished.

Output: one row per course, every course (also one without enrollments or lessons), ORDER BY course id: [course_id, title, enrolled, completed_all, avg_completion_pct]. enrolled = enrollments of the course whose status is not ''cancelled'' (the learners). completed_all = learners of the course whose number of lesson_progress rows for that course with completed_at NOT NULL equals the course''s number of lessons; 0 for a course without lessons; do not use the status ''completed'', which a separate job sets late. avg_completion_pct = ROUND(100.0 * (finished lessons of the course summed over its learners) / (enrolled * number of lessons), 1), the average of each learner''s completion percentage rounded to 1 decimal place, 0.0 when the course has no learners or no lessons. Progress of cancelled enrollments and of users not enrolled in the course never counts.

The test runner (do not change) builds an in-memory SQLite database from each test case, either small tables or a generated dataset of about 200 courses, 3,000 users, 10,000 enrollments and 50,000 progress rows. It runs INDEXES (CREATE INDEX statements only, not counted), then checks the plan of QUERY with EXPLAIN QUERY PLAN: a CORRELATED subquery is rejected as "too slow" because a report that reads every row must read each table once. Then it runs QUERY with a budget of 6,000,000 SQLite VM steps (set_progress_handler: steps are counted, not seconds, so the check is exact) and prints "too slow" with the plan when the budget is exceeded. Otherwise it prints the rows as a JSON list of lists, for example [[7, "Redis Patterns", 2, 1, 62.5]]. SQLite differs from PostgreSQL here: it has no EXPLAIN ANALYZE and shows a correlated subquery as CORRELATED SCALAR SUBQUERY where PostgreSQL shows a SubPlan; CTEs, LEFT JOIN, GROUP BY, CASE, COALESCE and aggregate FILTER work in both.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
