INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_412'), 1, 'Every subquery in the old report answers a question about one course or one learner. Which of those answers could you compute for all courses, or for all (user, course) pairs, in a single GROUP BY, and how small would that result be compared with the tables it reads?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_412'), 2, 'Look at three places: the finished-lesson count per learner (one GROUP BY over lesson_progress with the completed_at filter, keyed by user and course), the lesson count per course (one GROUP BY over lessons), and the final join from courses, which must keep courses without learners or lessons (LEFT JOIN plus COALESCE). Count learners before you join anything that has several rows per learner, or the counts multiply.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_412'), 3, 'The same shape on other tables: per category, the number of courses and how many have every lesson published. WITH lesson_totals AS (SELECT course_id, COUNT(*) AS total, SUM(CASE WHEN published THEN 1 ELSE 0 END) AS published FROM lessons GROUP BY course_id) SELECT c.category, COUNT(*) AS courses, SUM(CASE WHEN lt.total > 0 AND lt.published = lt.total THEN 1 ELSE 0 END) AS fully_published FROM courses AS c LEFT JOIN lesson_totals AS lt ON lt.course_id = c.id GROUP BY c.category ORDER BY c.category. The child table is reduced to one row per parent first, then joined once.');
