INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_pgp_421', (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-performance') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-4-2' AND is_deleted = false LIMIT 1), 'lock-contention-quiz', 'Who is waiting for whom?', 'Three pieces of evidence from CodeDev lock incidents: a migration that froze the enrollments table, a deadlock between two jobs, and a row locked with SELECT ... FOR UPDATE. Decide whether each statement is true or false.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
