WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_421'), 'At 14:02 a deploy ran a migration and the enrollments API started to time out. The on-call engineer ran this on PostgreSQL 16:

SELECT pid, state, wait_event_type AS wtype, now() - xact_start AS xact_age,
       pg_blocking_pids(pid) AS blocked_by, left(query, 52) AS query
FROM pg_stat_activity
WHERE datname = ''codedev'' AND xact_start IS NOT NULL
